alter table public.produkty add column if not exists kategoria text not null default 'Inne';
create table if not exists public.ceny_zakupow(id bigint generated by default as identity primary key,created_at timestamptz not null default now(),produkt_id bigint not null unique references public.produkty(id) on delete cascade,gramy_opakowania double precision not null default 0,cena_opakowania double precision not null default 0,cena_kg double precision not null default 0,status text not null default 'KUPIĆ');
alter table public.ceny_zakupow enable row level security;
grant select,insert,update,delete on public.ceny_zakupow to authenticated;
revoke all on public.ceny_zakupow from anon;
drop policy if exists "Zalogowani zarzadzaja cenami zakupow" on public.ceny_zakupow;
create policy "Zalogowani zarzadzaja cenami zakupow" on public.ceny_zakupow for all to authenticated using(true) with check(true);
